// Keeps the whole arena visible whatever the canvas size.
defineScript({
  name: 'ArenaCamera',
  description: 'Fits the camera zoom to the arena.',
  props: { margin: { type: 'number', default: 0.5, min: 0, max: 5 } },
  onUpdate(ctx) {
    const r = ctx.engine.renderer;
    if (!r) return;
    const gm = ctx.find('GameManager');
    const p = gm !== undefined ? ctx.getOn(gm, 'Script').props : null;
    const w = ((p && p.arenaWidth) || 32) + ctx.props.margin * 2;
    const h = ((p && p.arenaHeight) || 18) + ctx.props.margin * 2;
    const cam = ctx.get('Camera2D');
    cam.zoom = Math.min(r.width / (r.pixelsPerUnit * w), r.height / (r.pixelsPerUnit * h));
  },
});

// Drifting rock that splits into smaller rocks when destroyed. The polygon
// outline is generated from `seed`, so every peer draws the same shape.
function despawn(ctx, e) {
  const sync = ctx.net.hub.sync;
  if (sync && ctx.net.isHost) sync.despawn(e); else ctx.destroy(e);
}

defineScript({
  name: 'Asteroid',
  description: 'Wrapping asteroid that splits when shot.',
  props: {
    size: { type: 'integer', default: 3, min: 1, max: 3, label: 'Size (3 = large)' },
    seed: { type: 'integer', default: 1 },
    unitRadius: { type: 'number', default: 0.45, label: 'Radius per size step' },
  },
  onStart(ctx) {
    const size = ctx.props.size;
    const r = size * ctx.props.unitRadius;
    ctx.state.hp = size;
    const rng = new ctx.math.Random(ctx.props.seed);
    const n = 7 + size * 2;
    const pts = [];
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      const rr = r * rng.range(0.75, 1.15);
      pts.push(Math.cos(a) * rr, Math.sin(a) * rr);
    }
    const shape = ctx.get('Shape');
    shape.kind = 'polygon';
    shape.points = pts;
    const shade = rng.range(0.45, 0.65);
    shape.fill.set(shade, shade * 0.95, shade * 0.9, 1);
    const col = ctx.get('CircleCollider2D');
    col.radius = r * 0.92;
    const rb = ctx.get('RigidBody2D');
    rb.mass = size * size;
  },
  onFixedUpdate(ctx) {
    const gm = ctx.find('GameManager');
    const p = gm ? ctx.getOn(gm, 'Script').props : null;
    const w = (p && p.arenaWidth) || 32, h = (p && p.arenaHeight) || 18;
    const t = ctx.transform;
    if (t.x < -w / 2) t.x += w; else if (t.x > w / 2) t.x -= w;
    if (t.y < -h / 2) t.y += h; else if (t.y > h / 2) t.y -= h;
  },
  onMessage(ctx, name, data) {
    if (name !== 'hit' || !ctx.net.isHost || ctx.state.dead) return;
    ctx.state.hp -= data.damage;
    if (ctx.state.hp > 0) { ctx.audio.play('hit', { volume: 0.4, pitch: 0.8 }); return; }
    ctx.state.dead = true;
    const size = ctx.props.size;
    const t = ctx.transform;
    const rb = ctx.get('RigidBody2D');
    if (size > 1) {
      for (let i = 0; i < 2; i++) {
        const a = ctx.random.range(0, Math.PI * 2);
        const child = ctx.net.spawn('Asteroid', { position: { x: t.x + Math.cos(a) * 0.4, y: t.y + Math.sin(a) * 0.4 } });
        const cs = ctx.getOn(child, 'Script');
        cs.props.size = size - 1;
        cs.props.seed = ctx.random.int(1, 1e9);
        const crb = ctx.getOn(child, 'RigidBody2D');
        const sp = ctx.random.range(1.5, 3.5);
        crb.setVelocity(rb.velocity.x * 0.6 + Math.cos(a) * sp, rb.velocity.y * 0.6 + Math.sin(a) * sp);
        crb.angularVelocity = ctx.random.range(-2, 2);
      }
    }
    const boom = ctx.net.spawn('Explosion', { position: { x: t.x, y: t.y } });
    const bs = ctx.getOn(boom, 'Script');
    bs.props.count = 10 + size * 8;
    bs.props.color = '#c9c2b8';
    bs.props.shake = size * 0.06;
    ctx.audio.play('explosion', { volume: 0.35 + size * 0.15, pitch: 1.6 - size * 0.25 });
    ctx.send('asteroidDestroyed', { by: data.from, size });
    despawn(ctx, ctx.entity);
  },
});

// Short-lived projectile. Hits are resolved on the host and delivered to the
// target through a "hit" message, so ships and asteroids decide what to do.
function despawn(ctx, e) {
  const sync = ctx.net.hub.sync;
  if (sync && ctx.net.isHost) sync.despawn(e); else ctx.destroy(e);
}

defineScript({
  name: 'Bullet',
  description: 'Blaster shot: travels, wraps, damages what it touches.',
  props: {
    lifetime: { type: 'number', default: 1.1, min: 0.1, max: 10 },
    damage: { type: 'integer', default: 1, min: 1, max: 10 },
    shooter: { type: 'entity', default: 0 },
    shooterId: { type: 'string', default: '' },
    color: { type: 'string', default: '#ffd166', label: 'Colour (hex)' },
  },
  onStart(ctx) {
    ctx.state.age = 0;
    ctx.state.spent = false;
    const shape = ctx.get('Shape');
    if (shape) shape.fill.setHex(ctx.props.color);
    const light = ctx.get('Light2D');
    if (light) light.color.setHex(ctx.props.color);
  },
  onFixedUpdate(ctx, dt) {
    ctx.state.age += dt;
    if (ctx.state.age >= ctx.props.lifetime && ctx.net.isHost) { ctx.state.spent = true; despawn(ctx, ctx.entity); return; }
    const gm = ctx.find('GameManager');
    const p = gm ? ctx.getOn(gm, 'Script').props : null;
    const w = (p && p.arenaWidth) || 32, h = (p && p.arenaHeight) || 18;
    const t = ctx.transform;
    if (t.x < -w / 2) t.x += w; else if (t.x > w / 2) t.x -= w;
    if (t.y < -h / 2) t.y += h; else if (t.y > h / 2) t.y -= h;
  },
  onTriggerEnter(ctx, other) {
    if (!ctx.net.isHost || ctx.state.spent) return;
    if (other === ctx.props.shooter) return;
    const tag = ctx.getOn(other, 'Tag');
    if (!tag || tag.has('bullet')) return;
    if (tag.has('ship') || tag.has('asteroid')) {
      ctx.sendTo(other, 'hit', { damage: ctx.props.damage, from: ctx.props.shooterId });
      const spark = ctx.spawn('Explosion', { position: { x: ctx.transform.x, y: ctx.transform.y } });
      const sp = ctx.getOn(spark, 'Script');
      sp.props.count = 8; sp.props.color = ctx.props.color; sp.props.duration = 0.35; sp.props.light = 0.6;
      ctx.state.spent = true;
      despawn(ctx, ctx.entity);
    }
  },
});

// One-shot particle burst with a light flash; destroys itself afterwards.
defineScript({
  name: 'Explosion',
  description: 'Particle burst that removes itself.',
  props: {
    count: { type: 'integer', default: 30, min: 1, max: 500 },
    duration: { type: 'number', default: 0.9, min: 0.1, max: 5 },
    color: { type: 'string', default: '#ffd166', label: 'Colour (hex)' },
    shake: { type: 'number', default: 0, min: 0, max: 2, label: 'Camera shake' },
    light: { type: 'number', default: 2, min: 0, max: 10, label: 'Flash intensity' },
  },
  onStart(ctx) {
    const em = ctx.get('ParticleEmitter');
    em.startColor.setHex(ctx.props.color);
    em.endColor.setHex(ctx.props.color); em.endColor.a = 0;
    em.burst(ctx.props.count);
    const light = ctx.get('Light2D');
    if (light) { light.intensity = ctx.props.light; light.color.setHex(ctx.props.color); }
    if (ctx.props.shake > 0) {
      const cam = ctx.find('Camera');
      const c = cam !== undefined ? ctx.getOn(cam, 'Camera2D') : null;
      if (c) c.shake = Math.max(c.shake, ctx.props.shake);
    }
    ctx.timer(ctx.props.duration, () => ctx.destroy());
  },
  onUpdate(ctx, dt) {
    const light = ctx.get('Light2D');
    if (light) light.intensity = Math.max(0, light.intensity - dt * ctx.props.light * 3);
  },
});

// Host-side match logic: spawns one Ship per player, keeps asteroids in the
// arena, tracks scores and draws the HUD. Offline the local peer is the host,
// so the same code runs single-player and in a room.
function hud(ctx) { return ctx.engine.canvas ? ctx.engine.hud : null; }

const COLORS = ['#4cc2ff', '#ff7a3d', '#8b7dff', '#ffd166', '#06d6a0', '#ef476f', '#f78c6b', '#c8f0ff'];

defineScript({
  name: 'GameManager',
  description: 'Spawns players and asteroids, keeps score, shows the HUD.',
  props: {
    arenaWidth: { type: 'number', default: 32, min: 10, max: 100 },
    arenaHeight: { type: 'number', default: 18, min: 10, max: 60 },
    asteroids: { type: 'integer', default: 5, min: 0, max: 30, label: 'Asteroids to keep alive' },
    respawnDelay: { type: 'number', default: 2, min: 0, max: 10 },
    scoreToWin: { type: 'integer', default: 15, min: 1, max: 999 },
    asteroidScore: { type: 'integer', default: 1 },
    shipScore: { type: 'integer', default: 5 },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.players = {};          // peerId -> { entity, index, name, score }
    s.count = 0;
    s.unsub = [];
    s.over = false;
    if (!ctx.net.isHost) { this.drawHud(ctx); return; }

    this.addPlayer(ctx, ctx.net.localId);
    const sync = ctx.net.hub.sync;
    if (sync) {
      for (const p of sync.players()) if (p.peerId !== ctx.net.localId) this.addPlayer(ctx, p.peerId);
      s.unsub.push(sync.on('playerJoined', ({ peerId }) => this.addPlayer(ctx, peerId)));
      s.unsub.push(sync.on('playerLeft', ({ peerId }) => this.removePlayer(ctx, peerId)));
    }
    for (let i = 0; i < ctx.props.asteroids; i++) this.spawnAsteroid(ctx, 3, true);
    ctx.timer(3, () => this.topUpAsteroids(ctx), true);
    this.drawHud(ctx);
  },
  onDestroy(ctx) {
    for (const off of ctx.state.unsub) off();
    const h = hud(ctx);
    if (h) { h.remove('score'); h.remove('hint'); h.remove('winner'); }
  },

  addPlayer(ctx, peerId) {
    const s = ctx.state;
    if (s.players[peerId]) return;
    const index = s.count++;
    const pos = this.spawnPoint(ctx);
    const entity = ctx.net.spawn('Ship', { ownerId: peerId, position: pos });
    const pi = ctx.getOn(entity, 'PlayerInput');
    if (pi) pi.owner = peerId;
    const ni = ctx.getOn(entity, 'NetworkIdentity');
    if (ni) ni.ownerId = peerId;
    const name = ctx.getOn(entity, 'Name');
    if (name) name.name = `Ship ${peerId}`;
    // Pass per-player setup through the Script props: the ship reads them in onStart.
    const script = ctx.getOn(entity, 'Script');
    script.props.color = COLORS[index % COLORS.length];
    script.props.label = `P${index + 1}`;
    script.props.respawnDelay = ctx.props.respawnDelay;
    s.players[peerId] = { entity, index, name: `P${index + 1}`, score: 0 };
    this.drawHud(ctx);
  },
  removePlayer(ctx, peerId) {
    const p = ctx.state.players[peerId];
    if (!p) return;
    if (ctx.world.isAlive(p.entity)) {
      const sync = ctx.net.hub.sync;
      if (sync) sync.despawn(p.entity); else ctx.destroy(p.entity);
    }
    delete ctx.state.players[peerId];
    this.drawHud(ctx);
  },

  spawnPoint(ctx) {
    const w = ctx.props.arenaWidth, h = ctx.props.arenaHeight;
    for (let attempt = 0; attempt < 12; attempt++) {
      const x = ctx.random.range(-w / 2 + 2, w / 2 - 2), y = ctx.random.range(-h / 2 + 2, h / 2 - 2);
      if (ctx.physics.overlapCircle({ x, y }, 3).length === 0) return { x, y };
    }
    return { x: 0, y: 0 };
  },
  spawnAsteroid(ctx, size, anywhere) {
    const w = ctx.props.arenaWidth, h = ctx.props.arenaHeight;
    let x, y;
    if (anywhere) { const p = this.spawnPoint(ctx); x = p.x; y = p.y; }
    else if (ctx.random.chance(0.5)) { x = ctx.random.chance(0.5) ? -w / 2 + 0.5 : w / 2 - 0.5; y = ctx.random.range(-h / 2, h / 2); }
    else { x = ctx.random.range(-w / 2, w / 2); y = ctx.random.chance(0.5) ? -h / 2 + 0.5 : h / 2 - 0.5; }
    const e = ctx.net.spawn('Asteroid', { position: { x, y } });
    const script = ctx.getOn(e, 'Script');
    script.props.size = size;
    script.props.seed = ctx.random.int(1, 1e9);
    const rb = ctx.getOn(e, 'RigidBody2D');
    const a = ctx.random.range(0, Math.PI * 2), sp = ctx.random.range(0.8, 2.2) * (4 - size);
    rb.setVelocity(Math.cos(a) * sp, Math.sin(a) * sp);
    rb.angularVelocity = ctx.random.range(-1, 1);
    return e;
  },
  topUpAsteroids(ctx) {
    if (ctx.state.over) return;
    const alive = ctx.findAll('asteroid').length;
    if (alive < ctx.props.asteroids) this.spawnAsteroid(ctx, 3, false);
  },

  onMessage(ctx, name, data) {
    if (!ctx.net.isHost || ctx.state.over) return;
    if (name === 'asteroidDestroyed') this.award(ctx, data.by, ctx.props.asteroidScore);
    else if (name === 'shipDestroyed' && data.killer && data.killer !== data.victim) this.award(ctx, data.killer, ctx.props.shipScore);
  },
  award(ctx, peerId, points) {
    const p = ctx.state.players[peerId];
    if (!p) return;
    p.score += points;
    this.drawHud(ctx);
    if (p.score >= ctx.props.scoreToWin) this.endRound(ctx, p);
  },
  endRound(ctx, winner) {
    ctx.state.over = true;
    const h = hud(ctx);
    if (h) h.panel('winner', `${winner.name} wins!`, 'Next round starts in a moment');
    ctx.send('roundOver', { winner: winner.name });
    ctx.timer(4, () => {
      for (const p of Object.values(ctx.state.players)) p.score = 0;
      ctx.state.over = false;
      if (h) h.remove('winner');
      this.drawHud(ctx);
    });
  },

  drawHud(ctx) {
    const h = hud(ctx);
    if (!h) return;
    const me = ctx.net.localId;
    const rows = Object.entries(ctx.state.players)
      .sort((a, b) => b[1].score - a[1].score)
      .map(([id, p]) => `${id === me ? '▶ ' : '  '}${p.name.padEnd(4)} ${String(p.score).padStart(3)}`);
    h.text('score', rows.join('\n') || 'Waiting for players…', { anchor: 'top-left' });
    h.text('hint', `First to ${ctx.props.scoreToWin} · A/D turn · W thrust · J or click to fire`, { anchor: 'top' });
  },
});

// A player ship. Input arrives through onOwnerInput so the same script
// drives the local player and remote players on the host.
function arena(ctx) {
  const gm = ctx.find('GameManager');
  const p = gm ? ctx.getOn(gm, 'Script').props : null;
  return { w: (p && p.arenaWidth) || 32, h: (p && p.arenaHeight) || 18 };
}
function wrap(ctx) {
  const { w, h } = arena(ctx);
  const t = ctx.transform;
  let x = t.x, y = t.y, moved = false;
  if (x < -w / 2) { x += w; moved = true; } else if (x > w / 2) { x -= w; moved = true; }
  if (y < -h / 2) { y += h; moved = true; } else if (y > h / 2) { y -= h; moved = true; }
  if (moved) t.setPosition(x, y);
}

defineScript({
  name: 'Ship',
  description: 'Thrust/rotate (or twin-stick) ship with a blaster.',
  props: {
    controlMode: { type: 'enum', default: 'rotate', options: ['rotate', 'twin-stick'] },
    thrust: { type: 'number', default: 22, min: 1, max: 100 },
    turnSpeed: { type: 'number', default: 4.2, min: 0.5, max: 12, label: 'Turn speed (rad/s)' },
    maxSpeed: { type: 'number', default: 10, min: 1, max: 40 },
    fireInterval: { type: 'number', default: 0.16, min: 0.02, max: 2 },
    bulletSpeed: { type: 'number', default: 18, min: 1, max: 60 },
    hp: { type: 'integer', default: 3, min: 1, max: 20 },
    respawnDelay: { type: 'number', default: 2 },
    color: { type: 'string', default: '#4cc2ff', label: 'Colour (hex)' },
    label: { type: 'string', default: 'P1' },
  },
  onStart(ctx) {
    const s = ctx.state;
    s.hp = ctx.props.hp;
    s.cooldown = 0;
    s.dead = false;
    s.invuln = 1;
    s.spawn = { x: ctx.transform.x, y: ctx.transform.y };
    this.applyLook(ctx);
  },
  onReload(ctx) { this.applyLook(ctx); },
  applyLook(ctx) {
    const sprite = ctx.get('Sprite');
    if (sprite) sprite.tint.setHex(ctx.props.color);
    const light = ctx.get('Light2D');
    if (light) light.color.setHex(ctx.props.color);
    const em = ctx.get('ParticleEmitter');
    if (em) em.startColor.setHex(ctx.props.color);
    const plate = ctx.world.getChildren(ctx.entity)[0];
    const text = plate !== undefined ? ctx.getOn(plate, 'Text') : null;
    if (text) { text.text = ctx.props.label; text.color.setHex(ctx.props.color); }
  },

  onOwnerInput(ctx, snap, dt) {
    const s = ctx.state;
    if (s.dead) return;
    const rb = ctx.get('RigidBody2D');
    const t = ctx.transform;
    const mx = snap.axes.moveX || 0, my = snap.axes.moveY || 0;
    let thrusting = false;
    if (ctx.props.controlMode === 'twin-stick') {
      const len = Math.hypot(mx, my);
      if (len > 0.15) {
        const target = Math.atan2(my, mx) - Math.PI / 2;
        t.angle = ctx.math.lerpAngle(t.angle, target, Math.min(1, ctx.props.turnSpeed * 2 * dt));
        rb.applyForce(Math.cos(target + Math.PI / 2) * ctx.props.thrust * len, Math.sin(target + Math.PI / 2) * ctx.props.thrust * len);
        thrusting = true;
      }
    } else {
      if (mx !== 0) t.angle -= mx * ctx.props.turnSpeed * dt;
      if (my > 0.05) {
        const a = t.angle + Math.PI / 2;
        rb.applyForce(Math.cos(a) * ctx.props.thrust * my, Math.sin(a) * ctx.props.thrust * my);
        thrusting = true;
      } else if (my < -0.05) {
        rb.velocity.scale(1 - 0.9 * dt); // gentle brake
      }
    }
    const sp = rb.velocity.length();
    if (sp > ctx.props.maxSpeed) rb.velocity.scale(ctx.props.maxSpeed / sp);
    const em = ctx.get('ParticleEmitter');
    if (em) { em.emitting = thrusting; em.angle = t.angle - Math.PI / 2; }

    s.cooldown -= dt;
    if (snap.held.includes('fire') && s.cooldown <= 0) {
      s.cooldown = ctx.props.fireInterval;
      this.fire(ctx, rb);
    }
  },
  fire(ctx, rb) {
    const t = ctx.transform;
    const a = t.angle + Math.PI / 2;
    const dx = Math.cos(a), dy = Math.sin(a);
    const bullet = ctx.net.spawn('Bullet', { position: { x: t.x + dx * 0.8, y: t.y + dy * 0.8 } });
    const brb = ctx.getOn(bullet, 'RigidBody2D');
    brb.setVelocity(rb.velocity.x * 0.5 + dx * ctx.props.bulletSpeed, rb.velocity.y * 0.5 + dy * ctx.props.bulletSpeed);
    const script = ctx.getOn(bullet, 'Script');
    script.props.shooter = ctx.entity;
    script.props.shooterId = ctx.net.owner();
    script.props.color = ctx.props.color;
    const shape = ctx.getOn(bullet, 'Shape');
    if (shape) shape.fill.setHex(ctx.props.color);
    rb.applyImpulse(-dx * 0.4, -dy * 0.4);
    ctx.audio.play('laser', { volume: 0.5, pitchVariation: 0.1 });
  },

  onFixedUpdate(ctx, dt) {
    const s = ctx.state;
    if (s.dead) return;
    wrap(ctx);
    if (s.invuln > 0) {
      s.invuln -= dt;
      const sprite = ctx.get('Sprite');
      if (sprite) sprite.alpha = s.invuln > 0 ? 0.45 + 0.4 * Math.sin(ctx.time.elapsed * 30) : 1;
    }
  },
  onLateUpdate(ctx) {
    // Keep the name plate upright.
    const plate = ctx.world.getChildren(ctx.entity)[0];
    if (plate !== undefined) { const pt = ctx.getOn(plate, 'Transform'); pt.angle = -ctx.transform.angle; }
  },

  onCollisionEnter(ctx, other, info) {
    if (!ctx.net.isHost || ctx.state.dead) return;
    const tag = ctx.getOn(other, 'Tag');
    if (tag && tag.has('asteroid') && info.impulse > 5) this.damage(ctx, 1, null);
    else if (info.impulse > 3) ctx.audio.play('hit', { volume: 0.3 });
  },
  onMessage(ctx, name, data) {
    if (name === 'hit' && ctx.net.isHost) this.damage(ctx, data.damage, data.from);
  },
  damage(ctx, amount, from) {
    const s = ctx.state;
    if (s.dead || s.invuln > 0) return;
    s.hp -= amount;
    const sprite = ctx.get('Sprite');
    if (s.hp > 0) {
      if (sprite) { sprite.tint.setHex('#ffffff'); ctx.timer(0.08, () => sprite.tint.setHex(ctx.props.color)); }
      ctx.audio.play('hit', { volume: 0.6 });
      return;
    }
    s.dead = true;
    const boom = ctx.net.spawn('Explosion', { position: { x: ctx.transform.x, y: ctx.transform.y } });
    const bs = ctx.getOn(boom, 'Script');
    bs.props.color = ctx.props.color;
    bs.props.count = 60;
    bs.props.shake = 0.45;
    ctx.audio.play('explosion', { volume: 0.9 });
    ctx.send('shipDestroyed', { victim: ctx.net.owner(), killer: from });
    // Park the ship far away while dead; kinematic so nothing collides with it.
    const rb = ctx.get('RigidBody2D');
    rb.setVelocity(0, 0);
    rb.bodyType = 'kinematic';
    ctx.transform.setPosition(0, 1000);
    if (sprite) sprite.visible = false;
    const em = ctx.get('ParticleEmitter');
    if (em) em.emitting = false;
    ctx.timer(ctx.props.respawnDelay, () => this.respawn(ctx));
  },
  respawn(ctx) {
    const s = ctx.state;
    const { w, h } = arena(ctx);
    let x = 0, y = 0;
    for (let i = 0; i < 10; i++) {
      x = ctx.random.range(-w / 2 + 2, w / 2 - 2); y = ctx.random.range(-h / 2 + 2, h / 2 - 2);
      if (ctx.physics.overlapCircle({ x, y }, 3).length === 0) break;
    }
    const rb = ctx.get('RigidBody2D');
    rb.bodyType = 'dynamic';
    rb.setVelocity(0, 0);
    ctx.transform.setPosition(x, y);
    s.hp = ctx.props.hp;
    s.dead = false;
    s.invuln = 1.5;
    const sprite = ctx.get('Sprite');
    if (sprite) { sprite.visible = true; sprite.tint.setHex(ctx.props.color); }
  },
});
